package com.yesbee.nwtrack.workflow;

import com.yesbee.nwtrack.shared.ApiPage;
import com.yesbee.nwtrack.shared.Pages;

import com.yesbee.nwtrack.shared.ActorResolver;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;
import java.util.UUID;

@RestController @RequestMapping("/api/v1") @Tag(name="Operator workflow")
public class OperationsController {
    private final com.yesbee.nwtrack.production.LotTrolleyService trolleyMappings;private final OperationsService service;private final ActorResolver actors;private final JdbcTemplate jdbc;private final StationAccessService access;private final ProcessMachineService machineOperations;private final com.yesbee.nwtrack.auth.AccessPolicy policy;private final com.yesbee.nwtrack.users.ProcessAssignmentService assignments;
    public OperationsController(com.yesbee.nwtrack.production.LotTrolleyService trolleyMappings,OperationsService service,ActorResolver actors,JdbcTemplate jdbc,StationAccessService access,ProcessMachineService machineOperations,com.yesbee.nwtrack.auth.AccessPolicy policy,com.yesbee.nwtrack.users.ProcessAssignmentService assignments){this.trolleyMappings=trolleyMappings;this.service=service;this.actors=actors;this.jdbc=jdbc;this.access=access;this.machineOperations=machineOperations;this.policy=policy;this.assignments=assignments;}
    @PostMapping("/nfc/resolve") @PreAuthorize("isAuthenticated()") public Map<String,Object> resolve(@Valid @RequestBody NfcScan r){Map<String,Object> result=service.resolveNfc(r.uid());if("PAD".equals(policy.clientType())&&"STYLE_CONFIGURATOR".equals(policy.role())&&!"TROLLEY".equals(result.get("asset_type")))throw new org.springframework.security.access.AccessDeniedException("Only trolley tags are available in this workflow");UUID station=result.get("station_id")==null?null:(UUID)result.get("station_id");if(result.get("process_id")!=null)policy.process(policy.actor(),(UUID)result.get("process_id"));if(result.get("machine_id")!=null)policy.process(policy.actor(),jdbc.queryForObject("select process_id from machines where id=?",UUID.class,result.get("machine_id")));if(result.get("storage_area_id")!=null)station=jdbc.queryForObject("select station_id from storage_areas where id=?",UUID.class,result.get("storage_area_id"));if(result.get("storage_location_id")!=null)station=jdbc.queryForObject("select station_id from storage_locations where id=?",UUID.class,result.get("storage_location_id"));if(station!=null)policy.station(station);if(result.get("lot_id")!=null)policy.lot((UUID)result.get("lot_id"));UUID resolvedStation=station;result.put("processAssignments",assignments.list(policy.actor()).stream().filter(a->resolvedStation==null||resolvedStation.equals(a.stationId())).filter(a->result.get("process_id")==null||result.get("process_id").equals(a.processId())).toList());return result;}
    @PostMapping("/lots/{id}/trolley-link") @PreAuthorize("isAuthenticated()") public Map<String,Object> link(@PathVariable UUID id,@Valid @RequestBody TrolleyLink r,@AuthenticationPrincipal Jwt jwt){UUID actor=actors.id(jwt);if("PAD".equals(policy.clientType())&&"STYLE_CONFIGURATOR".equals(policy.role()))trolleyMappings.assign(id,r.trolleyId(),actor);else{access.assertCanOperateCurrentLotStation(actor,id);service.linkTrolley(id,r.trolleyId(),actor);}return service.resolveNfc(jdbc.queryForObject("select n.uid from nfc_tags n where n.trolley_id=? and n.active",String.class,r.trolleyId()));}
    @PostMapping("/lots/{id}/dispatch") @PreAuthorize("isAuthenticated()") public Map<String,Object> dispatch(@PathVariable UUID id,@AuthenticationPrincipal Jwt jwt){UUID actor=actors.id(jwt);access.assertCanOperateCurrentLotStation(actor,id);return service.dispatch(id,actor);}
    @PostMapping("/storage-locations/{id}/retrieve") @PreAuthorize("isAuthenticated()") public Map<String,Object> retrieve(@PathVariable UUID id,@Valid @RequestBody StorageRetrieve r,@AuthenticationPrincipal Jwt jwt){service.retrieveStorage(id,r.lotId(),r.trolleyId(),actors.id(jwt));return Map.of("retrieved",true,"lotId",r.lotId(),"trolleyId",r.trolleyId());}
    @PostMapping("/process-executions/{id}/{action:start|pause|resume|block|unblock|skip|complete}") @PreAuthorize("isAuthenticated()") public Map<String,Object> transition(@PathVariable UUID id,@PathVariable String action,@RequestBody(required=false) ActionRequest r,@AuthenticationPrincipal Jwt jwt){ActionRequest request=r==null?new ActionRequest(null,null,List.of(),null,null,null):r;String status;if("complete".equals(action)&&service.isFinalQuality(id)){policy.require("QC");if(request.passedQuantity()==null||request.rejectedQuantity()==null)throw new IllegalArgumentException("Final quality requires passedQuantity and rejectedQuantity");status=machineOperations.completeQuality(id,request.passedQuantity(),request.rejectedQuantity(),request.remarks(),actors.id(jwt));}else status=machineOperations.transition(id,action,request.reason(),request.processNfcUid(),request.machineNfcUids(),actors.id(jwt));return Map.of("id",id,"status",status);}
    @PostMapping("/process-executions/{id}/replace-machine") @PreAuthorize("isAuthenticated()") public Map<String,Object> replaceMachine(@PathVariable UUID id,@Valid @RequestBody MachineReplacement r,@AuthenticationPrincipal Jwt jwt){machineOperations.replaceMachine(id,r.oldMachineNfcUid(),r.newMachineNfcUid(),r.reason(),actors.id(jwt));return Map.of("id",id,"replaced",true);}
    @PostMapping("/process-executions/{id}/correction") @PreAuthorize("isAuthenticated()") public Map<String,Object> correction(@PathVariable UUID id,@Valid @RequestBody Correction r,@AuthenticationPrincipal Jwt jwt){return Map.of("id",id,"status",service.transition(id,r.targetStatus(),r.reason(),actors.id(jwt),true));}
    @PostMapping("/station-visits/{id}/wrong-station-override") @PreAuthorize("isAuthenticated()") public Map<String,Object> wrongStation(@PathVariable UUID id,@Valid @RequestBody WrongStationOverride r,@AuthenticationPrincipal Jwt jwt){access.assertCanOperate(actors.id(jwt),r.actualStationId());UUID actor=actors.id(jwt);Map<String,Object> visit=jdbc.queryForMap("select station_id,lot_id from station_visits where id=?",id);jdbc.update("update station_visits set station_id=?,version=version+1 where id=?",r.actualStationId(),id);jdbc.update("insert into audit_log(actor_id,action,object_type,object_id,outcome,reason,detail) values (?,'WRONG_STATION_OVERRIDE','STATION_VISIT',?,'SUCCESS',?,jsonb_build_object('expectedStationId',?,'actualStationId',?))",actor,id,r.reason(),visit.get("station_id"),r.actualStationId());return jdbc.queryForMap("select id,lot_id,station_id,status,version from station_visits where id=?",id);}
    @GetMapping("/stations/{id}/incoming") public ApiPage<Map<String,Object>> incoming(@PathVariable UUID id){return Pages.query(jdbc,"select sv.id visit_id,sv.lot_id,l.lot_number,l.quantity,l.status lot_status,l.style_id,s.style_number,l.current_route_sequence,l.current_location_type,l.current_location_id,l.created_at,l.completed_at,l.version,sv.station_id destination_station_id,sn.code destination_station,sn.name destination_station_name,sv.dispatched_at,t.id trolley_id,t.code trolley_code,"+LotProgressSql.columns(false)+" from station_visits sv join lots l on l.id=sv.lot_id join styles s on s.id=l.style_id join stations sn on sn.id=sv.station_id "+LotProgressSql.JOIN+" left join lot_trolley_assignments a on a.lot_id=l.id and a.released_at is null left join trolleys t on t.id=a.trolley_id where sv.station_id=? and sv.status='DISPATCHED' order by sv.dispatched_at,sv.id",id);}
    @GetMapping("/station-visits/{id}/processes") public ApiPage<Map<String,Object>> visitProcesses(@PathVariable UUID id){return Pages.query(jdbc,"select pe.id,pe.process_id,p.code,p.name,p.quality,p.nfc_mode,pe.sequence_no,pe.status,pe.started_at,pe.completed_at,pe.reason,pe.version from process_executions pe join processes p on p.id=pe.process_id where pe.station_visit_id=? and "+policy.processPredicate("pe.process_id")+" order by pe.sequence_no",id);}
    public record NfcScan(@NotBlank String uid){} public record TrolleyLink(@NotNull UUID trolleyId){} public record StorageRetrieve(@NotNull UUID lotId,@NotNull UUID trolleyId){} public record ActionRequest(String reason,String processNfcUid,List<String> machineNfcUids,Integer passedQuantity,Integer rejectedQuantity,String remarks){} public record MachineReplacement(@NotBlank String oldMachineNfcUid,@NotBlank String newMachineNfcUid,@NotBlank String reason){} public record Correction(@NotBlank String targetStatus,@NotBlank String reason){} public record WrongStationOverride(@NotNull UUID actualStationId,@NotBlank String reason){}
}
